import{_ as a,o as i,c as r,a5 as t}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Workspace Drive sync and upload readiness","description":"","frontmatter":{},"headers":[],"relativePath":"feature/customer-drive-workspace-sync/spec.md","filePath":"feature/customer-drive-workspace-sync/spec.md"}'),o={name:"feature/customer-drive-workspace-sync/spec.md"};function n(s,e,c,l,d,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="workspace-drive-sync-and-upload-readiness" tabindex="-1">Workspace Drive sync and upload readiness <a class="header-anchor" href="#workspace-drive-sync-and-upload-readiness" aria-label="Permalink to &quot;Workspace Drive sync and upload readiness&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Files uploaded directly into each mapped workspace Drive folder appear as private internal BrandHub materials; never import agency root files or another workspace. Google authorization must explicitly grant the configured broader scope; never silently broaden an existing grant.</p><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h2><ul><li>Scheduled additive import traverses mapped workspace folders, follows pagination, skips shortcuts/native Google documents and unsupported MIME. No whole-Drive scan. Stable per-connection/file identity prevents duplicates and resurrection of trash/purged materials.</li><li>Imported binaries can be read/downloaded through existing private capabilities. Default RAW/MATERIAL/INTERNAL; no automatic client visibility. Do not copy file bytes.</li><li>Upload readiness: bind explicit writes flag; verify truly empty agencies before initializing zero inventory. Agencies with preexisting metadata/reservations require real inventory. Missing agency Drive returns actionable error, no fallback during outage.</li><li>Imported originals participate in existing quota accounting and disconnect cleanup. Metadata import is recoverable across PG/Mongo failures; connection lease prevents disconnect races.</li></ul><h2 id="ui-i18n" tabindex="-1">UI / i18n <a class="header-anchor" href="#ui-i18n" aria-label="Permalink to &quot;UI / i18n&quot;">​</a></h2><p>Use existing UI/themes. Add library.upload.driveNotConnected in vi/en. No new palette. Existing permission checks remain.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Additive imports only; external rename/content/deletion reconciliation is not bidirectional editing. No automatic grant change; user performs Google consent. No auto-public sharing.</p><h2 id="accepted-google-permission" tabindex="-1">Accepted Google permission <a class="header-anchor" href="#accepted-google-permission" aria-label="Permalink to &quot;Accepted Google permission&quot;">​</a></h2><p>User explicitly chose full Drive scope for synchronization and existing deletion support. When sync is enabled, authorize requests <a href="https://www.googleapis.com/auth/drive" target="_blank" rel="noreferrer">https://www.googleapis.com/auth/drive</a>; completion stores and verifies the exact granted scope. Existing per-file grants stay readable but cannot import until the user reconnects. Imported files moved outside their workspace are blocked on read; disconnect preserves moved-out external files.</p>',11)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
